import {addItem,countItem,removeItem,ITEMS,equipmentClass,isBagSlot} from './inventory.js';
export const STOCK={smith:[{id:'sword_fine',count:1,price:30},{id:'bow_fine',count:1,price:30},{id:'mage_fine',count:1,price:30},{id:'arrow',count:10,price:3}],mary:[{id:'mary_ale',count:1,price:5},{id:'return_bone',count:1,price:8}],hunter:[{id:'hunter_stew',count:1,price:8}]};
for(const [id,item] of Object.entries(ITEMS))if(item.slot>=2&&item.slot<=5&&!item.citySet)STOCK.smith.push({id,count:1,price:{2:10,3:25,4:20,5:12}[item.slot]});
export const availableOffer=(p,offer)=>!!offer&&(offer.id!=='return_bone'||(p.maryBoneQuest==='done'||p.rewards.includes('c3-arrival')))&&(!ITEMS[offer.id]?.bagTier||ITEMS[offer.id].bagTier>(p.bagTier||0))&&(!equipmentClass(offer.id)||equipmentClass(offer.id)===p.classId)&&(offer.id!=='arrow'||p.classId==='bow');
export const SELL={cult_sign:6,bone:10,fang:5,carcass:3,mary_ale:2,sword_fine:15,bow_fine:15,mage_fine:15,shield_fine:15,quiver:15,grimoire:15};
for(const offer of STOCK.smith)if(ITEMS[offer.id].slot>=2)SELL[offer.id]=Math.floor(offer.price/2);
export function buy(p,slots,merchant,index){const offer=STOCK[merchant]?.[index];if(!(merchant.startsWith('order_')?p.rewards.includes('c3-arrival'):merchant.startsWith('city_')?['chapter_two','chapter_three','chapter_four'].includes(p.stage):merchant==='hunter'?p.rewards.includes('witch-quest'):p.rewards.includes('rabbit-quest'))||!offer)return 'Магазин пока закрыт.';if(!availableOffer(p,offer))return 'Этот товар предназначен для другого класса.';if(offer.id==='order_tonic'&&countItem(slots,offer.id)+offer.count>5)return 'Можно нести не больше5боевых настоек.';if(['mary_ale','return_bone'].includes(offer.id)&&countItem(slots,offer.id)+offer.count>(offer.id==='mary_ale'?12:5))return offer.id==='mary_ale'?'В инвентаре можно иметь не больше 12 порций эля.':'В инвентаре можно иметь не больше 5 косточек возвращения.';if((p.gold||0)<offer.price)return 'Недостаточно золота.';if(ITEMS[offer.id].bagTier){p.bagTier=ITEMS[offer.id].bagTier;while(slots.length<20+p.bagTier*6)slots.push(null);p.gold-=offer.price;return ''}const copy=slots.map(i=>i?{...i}:null);if(!addItem(copy,offer.id,offer.count))return 'Освободите место в сумке.';slots.splice(0,slots.length,...copy);p.gold=(p.gold||0)-offer.price;return ''}
export function sell(p,slots,index,{all=false}={}){const item=slots[index],price=SELL[item?.id];if(!p.rewards.includes('rabbit-quest')&&!p.rewards.includes('witch-quest')||!isBagSlot(index)||!item||!price)return 'Этот предмет не продаётся.';const amount=all?item.count:1;if(item.id==='arrow'){const credit=(p.arrowSaleRemainder||0)+amount;p.gold=(p.gold||0)+Math.floor(credit/10);p.arrowSaleRemainder=credit%10}else p.gold=(p.gold||0)+price*amount;item.count-=amount;if(!item.count)slots[index]=null;return ''}

export const weaponClass=id=>ITEMS[id]?.weaponClass||(['sword','bow','mage'].includes(id)?id:null);
export const weaponMultiplier=id=>ITEMS[id]?.damageMultiplier||1;

Object.assign(SELL,{hunter_stew:3,sword_bone:22,bow_bone:22,mage_bone:22});
export function craftBoneWeapon(p,slots){if(!p.rewards.includes('witch-quest')||!['sword','bow','mage'].includes(p.classId))return 'Охотник пока не может помочь.';if(countItem(slots,'bone')<8||countItem(slots,'fang')<5)return 'Нужно8костей и5клыков волка.';const copy=slots.map(i=>i?{...i}:null);removeItem(copy,'bone',8);removeItem(copy,'fang',5);if(!addItem(copy,p.classId+'_bone'))return 'Освободите ячейку в сумке для оружия.';slots.splice(0,slots.length,...copy);return ''}

export const MERCHANT_NAMES={smith:'Магазин Абвера',mary:'Магазин Мэри',hunter:'Лавка охотника',city_smith:'Кузница Греты',city_cook:'Кухня Лины',city_herbalist:'Травница Эльза',city_alchemist:'Алхимик Фабиан',city_leather:'Кожевник Торвальд'};
STOCK.city_smith=Object.entries(ITEMS).filter(([,i])=>i.citySet).map(([id,i])=>({id,count:1,price:{2:55,3:120,4:95,5:65}[i.slot]}));STOCK.city_smith.push({id:'arrow',count:10,price:3});
STOCK.city_cook=[{id:'hunter_stew',count:1,price:8},{id:'mary_ale',count:1,price:5}];STOCK.city_herbalist=[{id:'healing_herbs',count:1,price:5},{id:'health_potion',count:1,price:10}];STOCK.city_alchemist=[{id:'mana_potion',count:1,price:12},{id:'strength_potion',count:1,price:28}];STOCK.city_leather=[{id:'backpack_1',count:1,price:80},{id:'backpack_2',count:1,price:180},{id:'backpack_3',count:1,price:350}];
Object.assign(SELL,{bear_hide:12,werewolf_claw:30,healing_herbs:2});for(const o of STOCK.city_smith)if(o.id!=='arrow')SELL[o.id]=Math.floor(o.price/2);

export const MERCHANT_DESCRIPTIONS={city_leather:'Двойной щелчок — улучшить рюкзак. Новые ячейки останутся навсегда. Улучшение заменяет предыдущую сумку, повторная покупка недоступна.',city_smith:'Усиленные вальденские комплекты для вашего класса. Двойной щелчок — купить, правая кнопка по предмету из сумки — продать.',city_herbalist:'Травы и зелья здоровья для дороги. Двойной щелчок — купить.',city_alchemist:'Зелья магии и силы. Двойной щелчок — купить.',city_cook:'Рагу ускоряет восстановление шкал. Эль быстро восстанавливает силы. Двойной щелчок — купить.'};

STOCK.order_smith=['sword','bow','mage'].map(id=>({id:id+'_order',count:1,price:260}));STOCK.order_smith.push(...STOCK.city_smith);STOCK.order_supplies=[{id:'order_tonic',count:1,price:15},{id:'arrow',count:40,price:12},{id:'healing_herbs',count:1,price:5},{id:'health_potion',count:1,price:10},{id:'mana_potion',count:1,price:12},{id:'hunter_stew',count:1,price:8}];Object.assign(MERCHANT_NAMES,{order_smith:'Оружейная Серого дозора',order_supplies:'Припасы Бертольда'});Object.assign(MERCHANT_DESCRIPTIONS,{order_smith:'Оружие Ордена: +65% к базовому урону. Классовые товары, двойной щелчок — купить.',order_supplies:'Боевые настойки снимают замедление и оглушение; стрелы, лекарства и паёк для похода.'});Object.assign(SELL,{order_tonic:6,gargoyle_shard:12,blood_fang:10,sword_order:100,bow_order:100,mage_order:100});
export function craftOrderWeapon(p,slots){if(!p.rewards.includes('c3-scout'))return 'Сначала доложите о допросе разведчика.';if(countItem(slots,'gargoyle_shard')<8||countItem(slots,'blood_fang')<6||(p.gold||0)<35)return 'Нужно8осколков горгульи,6кровавых клыков и35золота.';const copy=slots.map(i=>i?{...i}:null);removeItem(copy,'gargoyle_shard',8);removeItem(copy,'blood_fang',6);if(!addItem(copy,p.classId+'_order'))return 'Освободите ячейку для оружия.';slots.splice(0,slots.length,...copy);p.gold-=35;return ''}

Object.assign(SELL,{moon_herb:8,dragon_scale:18,sword_ash:135,bow_ash:135,mage_ash:135});

SELL.arrow=1;for(const [id,item] of Object.entries(ITEMS))if(item.slot==='ring')SELL[id]=id.includes('dawn_')||id.includes('cinder_')?45:id.includes('order_')?30:18;
for(const [merchant,offers] of Object.entries({mary:[['healing_draught',12]],hunter:[['field_bandage',5]],city_herbalist:[['healing_draught',12],['greater_healing',24]],city_alchemist:[['healing_draught',12],['greater_healing',24]],order_supplies:[['return_bone',8],['healing_draught',12],['greater_healing',24]]}))for(const [id,price] of offers)STOCK[merchant].push({id,count:1,price});Object.assign(SELL,{healing_draught:5,greater_healing:10,field_bandage:2});
